import pathlib
for p in ['setup.py','pyproject.toml','setup.cfg','requirements.txt','requirements-dev.txt','requirements-tests.txt']:
    path=pathlib.Path(p)
    if path.exists():
        print(f'## {p}')
        for i,line in enumerate(path.read_text().splitlines(),1):
            if 'networkx' in line.lower() or 'install_requires' in line or 'dependencies' in line:
                print(f'{i}: {line}')
